use clap::{Arg, Command, value_parser, builder::PossibleValue, ArgAction};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::ffi::OsString;

fn build_cmd() -> Command {
    Command::new("nomino")
        .version("1.6.4")
        .about("Batch rename utility for developers")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .after_help("OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.")
        .after_long_help("OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.")
        .arg(Arg::new("dir").short('d').long("dir").value_name("PATH").help("Sets the working directory"))
        .arg(Arg::new("depth").long("depth").value_name("DEPTH").help("Optional value to overwrite inferred subdirectory depth value in 'regex' mode").value_parser(value_parser!(usize)))
        .arg(Arg::new("no-extension").short('E').long("no-extension").help("Does not preserve the extension of input files in 'sort' and 'regex' options").action(ArgAction::SetTrue))
        .arg(Arg::new("generate").short('g').long("generate").value_name("PATH").help("Stores a JSON map file in '<PATH>' after renaming files"))
        .arg(Arg::new("help").short('h').long("help").help("Print help (see more with '--help')").long_help("Print help (see a summary with '-h')").action(ArgAction::Help))
        .arg(Arg::new("mkdir").short('k').long("mkdir").help("Recursively creates all parent directories of '<OUTPUT>' if they are missing").action(ArgAction::SetTrue))
        .arg(Arg::new("map").short('m').long("map").visible_alias("from-file").value_name("PATH").help("Sets the path of map file to be used for renaming files"))
        .arg(Arg::new("max-depth").long("max-depth").value_name("DEPTH").help("Optional value to set the maximum of subdirectory depth value in 'regex' mode").value_parser(value_parser!(usize)))
        .arg(Arg::new("quiet").short('q').long("quiet").help("Does not print the map table to stdout").action(ArgAction::SetTrue))
        .arg(Arg::new("regex").short('r').long("regex").value_name("PATTERN").help("Regex pattern to match by filenames").requires("positional"))
        .arg(Arg::new("sort").short('s').long("sort").value_name("ORDER").help("Sets the order of natural sorting (by name) to rename files using enumerator").value_parser([PossibleValue::new("asc").help("Sort in ascending order"), PossibleValue::new("desc").help("Sort in descending order")]).ignore_case(true))
        .arg(Arg::new("test").short('t').long("test").visible_alias("dry-run").help("Runs in test mode without renaming actual files").action(ArgAction::SetTrue))
        .arg(Arg::new("version").short('V').long("version").help("Print version").action(ArgAction::Version))
        .arg(Arg::new("overwrite").short('w').long("overwrite").help("Overwrites output files, otherwise, a '_' is prepended to filename").action(ArgAction::SetTrue))
        .arg(Arg::new("positional").value_name("[SOURCE] OUTPUT").help("OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option").num_args(0..))
}

fn main() {
    let argv0 = std::env::args().next().unwrap_or_else(|| "executable".to_string());
    let cmd = build_cmd();
    // Use try_get_matches to intercept errors for bracket fix
    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            use clap::error::ErrorKind;
            if e.kind() == ErrorKind::MissingRequiredArgument {
                let mut msg = e.render().to_string();
                msg = msg.replace("[[SOURCE] OUTPUT]", "<[SOURCE] OUTPUT]");
                eprint!("{}", msg);
                std::process::exit(e.exit_code());
            } else {
                e.exit();
            }
        }
    };
    let code = run(matches, &argv0);
    std::process::exit(code);
}

fn run(matches: clap::ArgMatches, argv0: &str) -> i32 {
    // Extract args
    let dir_opt = matches.get_one::<String>("dir").cloned();
    let depth_opt = matches.get_one::<usize>("depth").copied();
    let no_ext = matches.get_flag("no-extension");
    let generate_opt = matches.get_one::<String>("generate").cloned();
    let mkdir_flag = matches.get_flag("mkdir");
    let map_opt = matches.get_one::<String>("map").cloned();
    let max_depth_opt = matches.get_one::<usize>("max-depth").copied();
    let quiet_flag = matches.get_flag("quiet");
    let regex_opt = matches.get_one::<String>("regex").cloned();
    let sort_opt = matches.get_one::<String>("sort").cloned();
    let test_flag = matches.get_flag("test");
    let overwrite_flag = matches.get_flag("overwrite");
    let positional: Vec<String> = matches.get_many::<String>("positional").map(|v| v.cloned().collect()).unwrap_or_default();

    let has_regex = regex_opt.is_some();
    let has_sort = sort_opt.is_some();
    let has_map = map_opt.is_some();

    // Custom validation
    if has_regex || has_sort || has_map {
        if positional.len() >= 2 {
            eprint!("error: optional SOURCE must be used without setting regex, map or sort flags\n");
            return 1;
        }
        if has_sort && !has_regex && positional.is_empty() {
            eprint!("error: [output-format] output formatter must be set\n");
            return 1;
        }
        // has_regex with empty is already handled by clap (requires), so unreachable
    } else {
        if positional.len() < 2 {
            eprint!("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.\nusage: run '{} --help' for more information.\n", argv0);
            return 1;
        }
    }

    // Determine work dir
    let work_dir = if let Some(d) = dir_opt {
        PathBuf::from(d)
    } else {
        PathBuf::from(".")
    };

    // Check work dir exists (try read_dir)
    match std::fs::read_dir(&work_dir) {
        Ok(_) => {},
        Err(e) => {
            eprint!("error: {}\n", e);
            return 1;
        }
    }
    // Also check if work_dir is dir? read_dir on file gives "Not a directory (os error 20)", which matches. Good.

    // Determine mode
    if has_regex {
        // regex mode, OUTPUT is positional[0]
        let output_pat = positional[0].clone();
        let source_pat = regex_opt.unwrap();
        return run_regex(&work_dir, &source_pat, &output_pat, depth_opt, max_depth_opt, no_ext, mkdir_flag, quiet_flag, test_flag, overwrite_flag, generate_opt);
    } else if has_sort {
        let output_pat = positional[0].clone();
        let sort_order = sort_opt.unwrap();
        let desc = sort_order.eq_ignore_ascii_case("desc");
        return run_sort(&work_dir, &output_pat, desc, no_ext, mkdir_flag, quiet_flag, test_flag, overwrite_flag, generate_opt);
    } else if has_map {
        let map_path = map_opt.unwrap();
        return run_map(&work_dir, &map_path, mkdir_flag, quiet_flag, test_flag, overwrite_flag, generate_opt);
    } else {
        // positional regex, last two
        let n = positional.len();
        let source_pat = positional[n-2].clone();
        let output_pat = positional[n-1].clone();
        return run_regex(&work_dir, &source_pat, &output_pat, depth_opt, max_depth_opt, no_ext, mkdir_flag, quiet_flag, test_flag, overwrite_flag, generate_opt);
    }
}

