fn format_tokens(tokens: &[Token], get_group: &dyn Fn(&str, Option<usize>) -> String) -> String {
    // get_group for named vs index? Actually we need to handle Index vs Named vs Auto (but Auto already resolved to Index).
    // For Index, call with numeric idx; for Named, call with name.
    // Padding handling: only for positive numbers (all ascii digits, non-empty, and value is digits? Or value after formatting? Original: padding only for positive numbers, e.g., "1" -> "001", "-1" -> "-1", "a" -> "a". So check if value string is all ascii digits (0-9) and non-empty? What about empty? Empty -> empty (no pad). What about "0"? All digits, pad? Yes "0" -> "000". Good. What about "00"? All digits, pad? "00" len2 pad3 -> "000" (pad to 3, adds 1 zero). Good (as we saw "00" -> "000"). Good.
    // So if value.chars().all(|c| c.is_ascii_digit()) && !value.is_empty(), then pad with '0' to width (if len < width, prepend zeros).
    // Else, no pad.
    let mut out = String::new();
    for tok in tokens {
        match tok {
            Token::Literal(s) => out.push_str(s),
            Token::Place(ph) => {
                let (val, pad) = match ph {
                    Placeholder::Auto { padding } => {
                        // Should not happen (autos resolved to Index), but handle as empty?
                        (String::new(), *padding)
                    },
                    Placeholder::Index { idx, padding } => {
                        let v = get_group(&idx.to_string(), Some(*idx));
                        (v, *padding)
                    },
                    Placeholder::Named { name, padding } => {
                        let v = get_group(name, None);
                        (v, *padding)
                    },
                };
                if let Some(width) = pad {
                    if !val.is_empty() && val.chars().all(|c| c.is_ascii_digit()) {
                        if val.len() < width {
                            for _ in 0..(width - val.len()) {
                                out.push('0');
                            }
                        }
                        out.push_str(&val);
                    } else {
                        out.push_str(&val);
                    }
                } else {
                    out.push_str(&val);
                }
            }
        }
    }
    out
}

// Natural sort
fn split_chunks(s: &str) -> Vec<(bool, String)> {
    // bool true if digit chunk (all ascii digits), false otherwise
    // Split by ascii digit vs non-digit
    let mut chunks = Vec::new();
    let mut cur = String::new();
    let mut cur_is_digit: Option<bool> = None;
    for c in s.chars() {
        let is_d = c.is_ascii_digit();
        match cur_is_digit {
            None => {
                cur.push(c);
                cur_is_digit = Some(is_d);
            },
            Some(prev) if prev == is_d => {
                cur.push(c);
            },
            Some(_) => {
                chunks.push((cur_is_digit.unwrap(), cur.clone()));
                cur.clear();
                cur.push(c);
                cur_is_digit = Some(is_d);
            }
        }
    }
    if !cur.is_empty() {
        chunks.push((cur_is_digit.unwrap(), cur));
    }
    chunks
}

fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    let ca = split_chunks(a);
    let cb = split_chunks(b);
    let mut i = 0;
    while i < ca.len() && i < cb.len() {
        let (a_is_d, a_s) = &ca[i];
        let (b_is_d, b_s) = &cb[i];
        if *a_is_d && *b_is_d {
            // both digit chunks
            let a_lead = a_s.starts_with('0');
            let b_lead = b_s.starts_with('0');
            match (a_lead, b_lead) {
                (true, false) => return Ordering::Less,
                (false, true) => return Ordering::Greater,
                (true, true) => {
                    // both leading, lexical
                    match a_s.cmp(b_s) {
                        Ordering::Equal => {},
                        ord => return ord,
                    }
                },
                (false, false) => {
                    // both non-leading, numeric: first by len, then lexical
                    match a_s.len().cmp(&b_s.len()) {
                        Ordering::Equal => {
                            match a_s.cmp(b_s) {
                                Ordering::Equal => {},
                                ord => return ord,
                            }
                        },
                        ord => return ord,
                    }
                }
            }
        } else {
            // at least one non-digit: remove whitespace and compare lexical
            // Remove all whitespace (char::is_whitespace)
            let a_filtered: String = a_s.chars().filter(|c| !c.is_whitespace()).collect();
            let b_filtered: String = b_s.chars().filter(|c| !c.is_whitespace()).collect();
            match a_filtered.cmp(&b_filtered) {
                Ordering::Equal => {},
                ord => return ord,
            }
        }
        i += 1;
    }
    // All equal so far, shorter (fewer chunks) is smaller? Or compare by remaining? Actually if one has more chunks, it's larger (since prefix).
    // But need to handle case where remaining chunks are all whitespace (which would be empty after filtering)? E.g., "a" vs "a "? Chunks: ["a"] vs ["a "]? Actually "a " splits into ["a "] (single non-digit chunk, since no digits). After filtering, both "a" equal, so equal (not shorter). Good. Our loop already compared first chunks (both non-digit) after filtering, equal, then i=1, ca.len()=1, cb.len()=1, so equal, return Equal (not shorter). Good.
    // For "a" vs "a0": chunks ["a"] vs ["a","0"]: first chunks "a" vs "a" equal, then ca has 1, cb has 2, so ca shorter => Less. Good.
    ca.len().cmp(&cb.len())
}

