    let quiet_flag = matches.get_flag("quiet");
    let regex_opt = matches.get_one::<String>("regex").cloned();
    let sort_opt = matches.get_one::<String>("sort").cloned();
    let test_flag = matches.get_flag("test");
    let overwrite_flag = matches.get_flag("overwrite");
    let positional: Vec<String> = matches.get_many::<String>("positional").map(|v| v.cloned().collect()).unwrap_or_default();

    let has_regex = regex_opt.is_some();
    let has_sort = sort_opt.is_some();
    let has_map = map_opt.is_some();

    if has_regex || has_sort || has_map {
        if positional.len() >= 2 {
