// Placeholder parsing
#[derive(Debug, Clone)]
enum Placeholder {
    Index { idx: usize, padding: Option<usize> },
    Named { name: String, padding: Option<usize> },
}

#[derive(Debug, Clone)]
enum Token {
    Literal(String),
    Place(Placeholder),
}

fn parse_output_pattern(pat: &str) -> Result<Vec<Token>, String> {
    let chars: Vec<char> = pat.chars().collect();
    let mut tokens: Vec<Token> = Vec::new();
    let mut literal = String::new();
    let mut i = 0usize;
    let mut auto_counter = 1usize;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            if i + 1 >= chars.len() {
                i += 1;
                continue;
            }
            let nxt = chars[i+1];
            if nxt == '{' || nxt == '}' || nxt == '\\' {
                literal.push(nxt);
                i += 2;
            } else {
                return Err(format!("invalid escape character of '{}' at '{}'", nxt, i+1));
            }
        } else if c == '{' {
            if !literal.is_empty() {
                tokens.push(Token::Literal(literal.clone()));
                literal.clear();
            }
            let mut content = String::new();
            let mut j = i + 1;
            let mut found = false;
            while j < chars.len() {
                let cj = chars[j];
                if cj == '\\' {
                    if j + 1 >= chars.len() {
                        j += 1;
                        continue;
                    }
                    let nj = chars[j+1];
                    if nj == '{' || nj == '}' || nj == '\\' {
                        content.push(nj);
                        j += 2;
                    } else {
                        return Err(format!("invalid escape character of '{}' at '{}'", nj, j+1));
                    }
                } else if cj == '{' {
                    content.push(cj);
                    j += 1;
                } else if cj == '}' {
                    found = true;
                    j += 1;
                    break;
                } else {
                    content.push(cj);
                    j += 1;
                }
            }
            if !found {
                return Err(format!("all opened placeholders must be closed by '}}'"));
            }
            let (g_str, p_opt_str) = if let Some(colon_idx) = content.find(':') {
                let (g, p_with_colon) = content.split_at(colon_idx);
                let p = &p_with_colon[1..];
                (g.to_string(), Some(p.to_string()))
            } else {
                (content.clone(), None)
            };
            let padding = if let Some(p_str) = p_opt_str {
                if p_str.is_empty() {
                    None
                } else {
                    match p_str.parse::<usize>() {
                        Ok(v) => Some(v),
                        Err(_) => return Err(format!("unable to parse padding of '{}'", p_str)),
                    }
                }
            } else {
                None
            };
            let placeholder = if g_str.is_empty() {
                let idx = auto_counter;
                auto_counter += 1;
                Placeholder::Index { idx, padding }
            } else if g_str.chars().all(|c| c.is_ascii_digit()) {
                match g_str.parse::<usize>() {
                    Ok(idx) => Placeholder::Index { idx, padding },
                    Err(_) => Placeholder::Named { name: g_str.clone(), padding },
                }
            } else {
                Placeholder::Named { name: g_str, padding }
            };
            tokens.push(Token::Place(placeholder));
            i = j;
        } else if c == '}' {
            return Err(format!("an unopened placeholder could not be closed by '}}'"));
        } else {
            literal.push(c);
            i += 1;
        }
    }
    if !literal.is_empty() {
        tokens.push(Token::Literal(literal));
    }
    Ok(tokens)
}

fn format_tokens(tokens: &[Token], get_group: &dyn Fn(&str, Option<usize>) -> String) -> String {
    let mut out = String::new();
    for tok in tokens {
        match tok {
            Token::Literal(s) => out.push_str(s),
            Token::Place(ph) => {
                let (val, pad) = match ph {
                    Placeholder::Index { idx, padding } => {
                        let v = get_group(&idx.to_string(), Some(*idx));
                        (v, *padding)
                    },
                    Placeholder::Named { name, padding } => {
                        let v = get_group(name, None);
                        (v, *padding)
                    },
                };
                if let Some(width) = pad {
                    if !val.is_empty() && val.chars().all(|c| c.is_ascii_digit()) {
                        if val.len() < width {
                            for _ in 0..(width - val.len()) {
                                out.push('0');
                            }
                        }
                        out.push_str(&val);
                    } else {
                        out.push_str(&val);
                    }
                } else {
                    out.push_str(&val);
                }
            }
        }
    }
    out
}

// Natural sort
fn split_chunks(s: &str) -> Vec<(bool, String)> {
    let mut chunks = Vec::new();
    let mut cur = String::new();
    let mut cur_is_digit: Option<bool> = None;
    for c in s.chars() {
        let is_d = c.is_ascii_digit();
        match cur_is_digit {
            None => {
                cur.push(c);
                cur_is_digit = Some(is_d);
            },
            Some(prev) if prev == is_d => {
                cur.push(c);
            },
            Some(_) => {
                chunks.push((cur_is_digit.unwrap(), cur.clone()));
                cur.clear();
                cur.push(c);
                cur_is_digit = Some(is_d);
            }
        }
    }
    if !cur.is_empty() {
        chunks.push((cur_is_digit.unwrap(), cur));
    }
    chunks
}

fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    let ca = split_chunks(a);
    let cb = split_chunks(b);
    let mut i = 0;
    while i < ca.len() && i < cb.len() {
        let (a_is_d, a_s) = &ca[i];
        let (b_is_d, b_s) = &cb[i];
        if *a_is_d && *b_is_d {
            let a_lead = a_s.starts_with('0');
            let b_lead = b_s.starts_with('0');
            match (a_lead, b_lead) {
                (true, false) => return Ordering::Less,
                (false, true) => return Ordering::Greater,
                (true, true) => {
                    match a_s.cmp(b_s) {
                        Ordering::Equal => {},
                        ord => return ord,
                    }
                },
                (false, false) => {
                    match a_s.len().cmp(&b_s.len()) {
                        Ordering::Equal => {
                            match a_s.cmp(b_s) {
                                Ordering::Equal => {},
                                ord => return ord,
                            }
                        },
                        ord => return ord,
                    }
                }
            }
        } else {
            let a_filtered: String = a_s.chars().filter(|c| !c.is_whitespace()).collect();
            let b_filtered: String = b_s.chars().filter(|c| !c.is_whitespace()).collect();
            match a_filtered.cmp(&b_filtered) {
                Ordering::Equal => {},
                ord => return ord,
            }
        }
        i += 1;
    }
    ca.len().cmp(&cb.len())
}

fn prepend_underscore(desired: &str) -> String {
    let p = Path::new(desired);
    if let Some(fname) = p.file_name() {
        let parent = p.parent().unwrap_or(Path::new(""));
        let new_fname = format!("_{}", fname.to_string_lossy());
        if parent.as_os_str().is_empty() {
            new_fname
        } else {
            parent.join(&new_fname).to_string_lossy().to_string()
        }
    } else {
        p.join("_").to_string_lossy().to_string()
    }
}

fn ensure_parent_dirs(path_str: &str) {
    let p = Path::new(path_str);
    if let Some(parent) = p.parent() {
        if !parent.as_os_str().is_empty() {
            let _ = std::fs::create_dir_all(parent);
        }
    }
}

fn display_width(s: &str) -> usize {
    use unicode_width::UnicodeWidthStr;
    s.width()
}

fn print_table(rows: &[(String, String)]) {
    if rows.is_empty() {
        return;
    }
    // rows are (input, output) already sorted by output
    // Split each cell by '\n' for multiline
    // Compute widths based on display width of each line
    let header_in = "Input";
    let header_out = "Output";
    let mut w_in = display_width(header_in);
    let mut w_out = display_width(header_out);
    // For each row, split
    let mut split_rows: Vec<(Vec<String>, Vec<String>)> = Vec::new();
    for (inp, out) in rows {
        let in_lines: Vec<String> = inp.split('\n').map(|s| s.to_string()).collect();
        let out_lines: Vec<String> = out.split('\n').map(|s| s.to_string()).collect();
        for l in &in_lines {
            let w = display_width(l);
            if w > w_in { w_in = w; }
        }
        for l in &out_lines {
            let w = display_width(l);
            if w > w_out { w_out = w; }
        }
        split_rows.push((in_lines, out_lines));
    }
    // Print
    // Border: +-----+-----+
    // Each col: "+" + "-"*(w+2) 
    let border = format!("+{}+{}+", "-".repeat(w_in+2), "-".repeat(w_out+2));
    println!("{}", border);
    // Header: "| Input | Output |" with padding
    // Format: "| " + content padded to width (using display width) + " | "
    // Need to pad based on display width, not char len.
    fn pad_cell(s: &str, width: usize) -> String {
        let w = display_width(s);
        if w >= width {
            s.to_string()
        } else {
            let mut r = s.to_string();
            for _ in 0..(width - w) {
                r.push(' ');
            }
            r
        }
    }
    println!("| {} | {} |", pad_cell(header_in, w_in), pad_cell(header_out, w_out));
    println!("{}", border);
    for (in_lines, out_lines) in split_rows {
        let n = std::cmp::max(in_lines.len(), out_lines.len());
        for idx in 0..n {
            let il = if idx < in_lines.len() { &in_lines[idx] } else { "" };
            let ol = if idx < out_lines.len() { &out_lines[idx] } else { "" };
            println!("| {} | {} |", pad_cell(il, w_in), pad_cell(ol, w_out));
        }
    }
    println!("{}", border);
}

