        // However, need to handle that with_final is already sorted by desired (before _ handling), but after _ handling, order may differ. Deduping by keeping last in current order, then sorting by final for table, should match.
        let mut map_dedup: BTreeMap<String, String> = BTreeMap::new(); // output -> input (last wins)
        // To keep last, iterate in order and insert (overwrite)
