            // Processing order is mappings order (desired-sorted).
            let mut temp_successes: Vec<(String, String)> = Vec::new(); // in processing order (may have duplicates)
            for (inp, desired) in mappings {
                let src = Path::new(&inp);
                let dst = Path::new(&desired);
                match std::fs::rename(src, dst) {
                    Ok(_) => {
