        // Actually successes from BTreeMap iteration is sorted. For actual without overwrite, we sorted. Good.
        print_table(&successes);
    }

    if has_error { 1 } else { 0 }
}

fn run_sort(output_pat: &str, desc: bool, no_ext: bool, mkdir_flag: bool, quiet_flag: bool, test_flag: bool, overwrite_flag: bool, generate_opt: Option<String>) -> i32 {
    let tokens = match parse_output_pattern(output_pat) {
        Ok(v) => v,
        Err(msg) => {
            eprint!("error: [output-format] {}\n", msg);
            return 1;
        }
    };
    let mut entries: Vec<std::ffi::OsString> = Vec::new();
    let read = match std::fs::read_dir(".") {
        Ok(r) => r,
        Err(e) => {
            eprint!("error: {}\n", e);
            return 1;
        }
    };
    for ent in read {
        let ent = match ent {
            Ok(e) => e,
            Err(_) => continue,
        };
        entries.push(ent.file_name());
    }
    if entries.is_empty() {
        if let Some(g) = generate_opt {
            let empty_map: BTreeMap<String,String> = BTreeMap::new();
            match serde_json::to_string_pretty(&empty_map) {
                Ok(s) => {
                    if let Err(e) = std::fs::write(&g, s) {
                        eprint!("error: {}\n", e);
                        return 1;
                    }
                },
                Err(e) => {
                    eprint!("error: {}\n", e);
                    return 1;
                }
            }
        }
        return 0;
    }
    let mut entries_with_lossy: Vec<(std::ffi::OsString, String)> = entries.into_iter().map(|os| {
        let lossy = os.to_string_lossy().to_string();
        (os, lossy)
    }).collect();
    entries_with_lossy.sort_by(|a,b| {
        let ord = natural_cmp(&a.1, &b.1);
        if desc { ord.reverse() } else { ord }
    });
    struct Desired { input_display: String, desired: String }
    let mut desired_list: Vec<Desired> = Vec::new();
    for (idx, (input_os, input_lossy)) in entries_with_lossy.iter().enumerate() {
        let enumerator = (idx + 1).to_string();
        let filename = input_lossy.clone();
        let get_group = |name: &str, num: Option<usize>| -> String {
            if let Some(n) = num {
                if n == 0 {
                    filename.clone()
                } else if n == 1 {
                    enumerator.clone()
                } else {
                    String::new()
                }
            } else {
                let _ = name;
                String::new()
            }
        };
        let mut out_str = format_tokens(&tokens, &get_group);
        if !no_ext {
            let input_path = Path::new(input_os);
            if let Some(ext_os) = input_path.extension() {
                let ext_lossy = ext_os.to_string_lossy();
                out_str.push('.');
                out_str.push_str(&ext_lossy);
            }
        }
        desired_list.push(Desired { input_display: input_lossy.clone(), desired: out_str });
    }
    desired_list.sort_by(|a,b| a.desired.cmp(&b.desired));
    let mappings: Vec<(String, String)> = desired_list.into_iter().map(|d| (d.input_display, d.desired)).collect();
    return process_mappings(mappings, mkdir_flag, quiet_flag, test_flag, overwrite_flag, generate_opt);
}

