            let get_group = |name: &str, num: Option<usize>| -> String {
                if let Some(n) = num {
                    if let Some(m) = caps.get(n) {
                        m.as_str().to_string()
                    } else {
                        String::new()
                    }
                } else {
                    if let Some(m) = caps.name(name) {
                        m.as_str().to_string()
                    } else {
