fn run_map(map_path_str: &str, mkdir_flag: bool, quiet_flag: bool, test_flag: bool, overwrite_flag: bool, generate_opt: Option<String>) -> i32 {
    // Read map file (relative to cwd=work_dir, absolute as is)
    let content = match std::fs::read_to_string(map_path_str) {
        Ok(c) => c,
        Err(e) => {
            eprint!("error: {}\n", e);
            return 1;
        }
    };
    let parsed: Result<BTreeMap<String, String>, _> = serde_json::from_str(&content);
    let map: BTreeMap<String, String> = match parsed {
        Ok(m) => m,
        Err(e) => {
            eprint!("error: {}\n", e);
            return 1;
        }
    };
    if map.is_empty() {
        if let Some(g) = generate_opt {
            let empty_map: BTreeMap<String,String> = BTreeMap::new();
            match serde_json::to_string_pretty(&empty_map) {
                Ok(s) => {
                    if let Err(e) = std::fs::write(&g, s) {
                        eprint!("error: {}\n", e);
                        return 1;
                    }
                },
                Err(e) => {
                    eprint!("error: {}\n", e);
                    return 1;
                }
            }
        }
        return 0;
    }
    // map is BTreeMap sorted by input (key). Need to sort by output (value) stable for processing.
    // Collect to Vec in input-sorted order (BTreeMap iteration), then stable sort by output.
    let mut desired_list: Vec<(String, String)> = map.into_iter().map(|(k,v)| (k,v)).collect();
    // desired_list is sorted by input (since BTreeMap). Stable sort by output.
    desired_list.sort_by(|a,b| a.1.cmp(&b.1));
    return process_mappings(desired_list, mkdir_flag, quiet_flag, test_flag, overwrite_flag, generate_opt);
}
